<?php $activeTitle=$activeConversation?($activeConversation['participant_name']??$activeConversation['subject']??'Conversation'):null; ?>
<main class="main"><div class="main__inner"><div class="module-page">
<header class="module-page__header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Messaging</span></nav><h1>Messaging</h1><p>Private institute conversations with participant access control.</p></div></header>
<section class="module-card"><div class="module-card__body"><details class="messaging-compose"<?=!$conversations?' open':''?>><summary><i data-lucide="square-pen"></i>Start a new conversation</summary><form method="post" action="<?=url('/admin/communication/messaging')?>"><?=csrf_field()?><div class="module-form-grid"><div class="module-field"><label for="messageRecipient">Recipient</label><select class="module-select" id="messageRecipient" name="recipient_id" required><option value="">Select recipient</option><?php foreach($recipients as$r):?><option value="<?=(int)$r['id']?>"><?=e($r['name'].' — '.$r['email'])?></option><?php endforeach?></select></div><div class="module-field"><label for="messageSubject">Subject <span class="optional-label">Optional</span></label><input class="module-input" id="messageSubject" name="subject" maxlength="150"></div><div class="module-field field--wide"><label for="messageBody">Message</label><textarea class="module-textarea" id="messageBody" name="message" required></textarea></div></div><div class="filter-actions"><button class="btn btn--primary" type="submit"><i data-lucide="send"></i>Send message</button></div></form></details></div></section>
<section class="module-card chat-layout" aria-label="Institute conversations"><aside class="chat-list"><header class="chat-list__header"><div><h2>Conversations</h2><p class="record-count"><?=count($conversations)?> total</p></div></header><div class="conversation-list"><?php foreach($conversations as$c):$name=$c['participant_name']?:$c['subject']?:'Conversation';?><a href="<?=url('/admin/communication/messaging?conversation='.$c['id'])?>" class="module-card__body conversation-item"<?=$activeConversation&&(int)$activeConversation['id']===(int)$c['id']?' aria-current="page"':''?>><span class="conversation-avatar" aria-hidden="true"><?=e(strtoupper(substr((string)$name,0,1)))?></span><span class="conversation-copy"><strong><?=e($name)?></strong><small><?=e($c['updated_at'])?></small></span><?php if($c['unread_count']):?><span class="status-badge"><?=(int)$c['unread_count']?> new</span><?php endif?></a><?php endforeach?><?php if(!$conversations):?><div class="compact-empty"><div><span class="compact-empty__icon"><i data-lucide="messages-square"></i></span><h3>No conversations yet</h3><p>Start a conversation when you are ready.</p></div></div><?php endif?></div></aside>
<div class="module-card__body chat-pane"><?php if($activeConversation):?><header class="chat-pane__header"><h2><?=e((string)$activeTitle)?></h2><p><?=e($activeConversation['subject']??'Institute conversation')?></p></header><div class="chat-history" aria-live="polite"><?php foreach($activeConversation['messages']as$m):?><article class="notice-panel chat-bubble"><div><strong><?=e($m['sender_name'])?></strong><p><?=nl2br(e($m['body']))?></p><small><?=e($m['created_at'])?></small></div></article><?php endforeach?></div><form class="chat-reply" method="post" action="<?=url('/admin/communication/messaging/'.$activeConversation['id'])?>"><?=csrf_field()?><div class="module-field"><label class="sr-only" for="chatReply">Reply</label><textarea class="module-textarea" id="chatReply" name="message" placeholder="Write a reply…" required></textarea></div><button class="btn btn--primary" type="submit"><i data-lucide="send"></i>Send</button></form><?php else:?><div class="compact-empty"><div><span class="compact-empty__icon"><i data-lucide="message-circle"></i></span><h3>Select a conversation</h3><p>Choose a conversation from the list to read and reply.</p></div></div><?php endif?></div></section>
</div></div></main>
